"use client";
import { createContext, useContext } from "react";
const HeadingAnchorsContext = createContext(true);
const HeadingAnchorsProvider = HeadingAnchorsContext.Provider;
function useHeadingAnchors() {
  return useContext(HeadingAnchorsContext);
}
export {
  HeadingAnchorsProvider,
  useHeadingAnchors
};
